head.script:
// 테스트 설명, 유효성 값 설정
// interactionEnterKey 별 요청 시점 / submissionFunc 파라미터(검색어·키 코드) 검증 담당
// (_1 은 동적 요청·search/listModeOnFocus 미적용·false 동작, _2 는 submission 방식·아이템 반영·submission/submissionFunc 미설정 담당)
scwin.tData = {
    "description" : "[autoComplete > P > interactionMode]<br/>입력값을 검색키로 사용하여 아이템을 동적으로 요청할지 설정합니다.",
    "validation" : [
        "아이템 데이터 요청은 다음의 경우에 submission 또는 submissionFunc 속성에 설정된 방식으로 실행됩니다. interactionEnterKey='false' 인 경우 사용자의 입력값이 바뀔 때와 아이템 리스트창이 닫힌 상태에서 아래 화살표키를 누를 때 실행됩니다.",
        "아이템 데이터 요청은 다음의 경우에 submission 또는 submissionFunc 속성에 설정된 방식으로 실행됩니다. interactionEnterKey='true' 인 경우 Enter 키를 누를 때만 실행됩니다.",
        "검색키는 다음과 같이 전달됩니다. submissionFunc : 사용자 정의 함수의 파라미터로 검색어와 입력한 키의 키 코드가 전달됩니다."
    ]
}

// submissionFunc 가 검색 결과로 추가할 아이템 (초기 아이템은 두지 않음)
scwin.arrCity = [
    { "label" : "Seoul", "value" : "SEL" },
    { "label" : "Seongnam", "value" : "SNM" },
    { "label" : "Busan", "value" : "PUS" },
    { "label" : "Jeju", "value" : "CJU" }
];

// submissionFunc 호출 기록 (요청 확인 버튼 클릭 시 출력 후 비움)
scwin.arrRequest = [];



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 기본값 : interactionEnterKey=false
    con_interactionEnterKey.setValue("3");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') target1.remove();

    $c.gcm.createLabel('label="[전제]\n- interactionMode=true 고정, submissionFunc 는 검색어를 포함하는 아이템(Seoul, Seongnam, Busan, Jeju 중)을 목록에 표시\n- 직전 검색어와 같으면 다시 요청하지 않으므로 Target 재생성 후 시작\n- 아래 화살표키는 목록이 닫혀 있고 입력값이 직전 검색어와 다를 때만 요청\n- 요청 확인 클릭은 편집 모드를 해제하므로 절차 마지막에만 클릭\n[절차]\n입력창 클릭 -> eo 입력(interactionEnterKey=true 는 Enter 추가) -> 목록에서 Seoul 클릭 -> 입력창 클릭 -> 아래 화살표키 -> 요청 확인\n[확인] 요청 횟수와 검색어(keyCode : 13=Enter, 40=아래 화살표키, 그 외=입력 문자)"', '', 'label1');

    scwin.arrRequest = [];

    let properties = {
        interactionMode : "true",
        interactionEnterKey : con_interactionEnterKey.getText(),
        submissionFunc : "scwin.searchItem",
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices></w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// interactionMode=true 일때 아이템 데이터 요청 함수 : 검색어·키 코드 기록 후 검색어를 포함하는 아이템으로 목록을 바꾸고 리스트창 표시
scwin.searchItem = function (searchStr, keyCode) {
    scwin.arrRequest.push((searchStr === "" ? "(빈 문자열)" : searchStr) + "(" + keyCode + ")");
    target1.removeAll();
    scwin.arrCity.forEach(function (item) {
        if (item.label.indexOf(searchStr) > -1) {
            target1.addItem(item.label, item.value);
        }
    });
    target1.openTable();
};



// 직전 확인 이후의 아이템 데이터 요청 횟수와 검색어(keyCode) 출력 후 기록 비움 (validation 1 ~ 3)
scwin.btn_getRequest_onclick = function (e) {
    let strResult = "요청 횟수 : " + scwin.arrRequest.length;
    if (scwin.arrRequest.length > 0) {
        strResult += " -> 검색어(keyCode) : " + scwin.arrRequest.join(" / ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue(strResult);
    scwin.arrRequest = [];
};
